const M=BuildModel,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='build-intelligence-demo-v2';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==2||!Array.isArray(state.requests)||!Array.isArray(state.records)||!Array.isArray(state.materials)||!Array.isArray(state.notices))state=M.seed()}catch{state=M.seed()}
let sharedModel=globalThis.SPATIA_ACTIVE_MODEL;if(sharedModel){if(!state.buildingId&&state.requests.some(r=>r.element?.startsWith('A-')))state.buildingId='forest-a-demo';state=SpatiaWorkspace.reconcile(state,sharedModel);try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
let role='resident',page='home',unit=M.activeUnit||'302',selectedSpace='bedroom',selectedElement='A-302-W01',selectedRequest='REQ-2026-001',filter='',statusFilter='all';
if(sharedModel){const q=typeof location==='object'?new URLSearchParams(location.search).get('element'):null;selectedElement=sharedModel.elements.some(e=>e.id===q)?q:sharedModel.elements.find(e=>e.unit===unit)?.id||sharedModel.elements[0].id;}
const own=()=>M.visibleRequests(state,role),records=()=>M.visibleRecords(state,role),unitName=u=>u==='common'?'공용부':`A동 ${u}호`,spaceName=s=>M.spaces.find(x=>x.id===s)?.name||({corridor:'복도',elevator:'엘리베이터',stairs:'계단'}[s])||s;
const badge=r=>`<span class="badge ${r.stage>=4?'green':r.stage===0?'gray':''}">${M.stages[r.stage]}</span>`;
const dateText=d=>d?esc(d.slice(0,10).replaceAll('-','.')):'일정 미정';
function commit(fn){const next=M.clone(state);try{fn(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return true}catch(e){toast(e.name==='QuotaExceededError'?'저장 공간이 부족합니다. 사진 수·크기를 줄여 다시 저장하세요.':e.message);return false}}
let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function show(html){$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()};const close=()=>$('#dialog').close();$('#close').onclick=close;$('#dialog').onclick=e=>{if(e.target===$('#dialog'))close()};
const menu={resident:[['home','◫','우리 집 대시보드'],['requests','⌁','나의 관리 요청'],['records','▤','점검·보수 이력'],['knowledge','✧','쉬운 건축 이야기'],['schedule','▦','공용시설 일정']],manager:[['home','◫','건물 관리 대시보드'],['requests','⌁','전체 요청 관리'],['approvals','✓','정보 공개 승인'],['insights','◉','반복 하자 분석'],['schedule','▦','점검·보수 일정'],['reports','↗','데이터 내보내기']],expert:[['home','◫','공간·구조물 지도'],['requests','⌁','현장 요청 조회'],['materials','▥','자재·시공 기록'],['records','▤','점검·보수 기록'],['knowledge','✧','쉬운 설명 작성']]};
const titles={resident:['MY HOME, BETTER CONNECTED','안녕하세요, 더 안심되는 일상을 위해','우리 집의 상태부터 관리 요청까지, 공간 위에서 한눈에 확인하세요.'],manager:['BUILDING OPERATIONS','공간의 신호를 모아, 더 빠른 관리로','요청 접수부터 보수 완료까지, 건물의 모든 변화를 연결합니다.'],expert:['SPATIAL QUALITY MANAGEMENT','현장의 기록이, 건물의 신뢰가 됩니다','구조물·자재·점검 이력을 공간 ID로 연결해 확인하세요.']};
function render(){if(sharedModel){const card=document.querySelector('.building-card>div');if(card)card.innerHTML=esc(sharedModel.name)+'<small>'+esc(SpatiaWorkspace.buildingId(sharedModel))+'</small>';let banner=document.querySelector('#modelConnection');if(!banner){banner=document.createElement('div');banner.id='modelConnection';banner.className='workspace-banner';document.querySelector('.rolebar').after(banner)}banner.innerHTML='로컬 역할 체험 · '+esc(sharedModel.name)+' · 구조물 ID·자재 공유 · 미연결 요청 '+state.requests.filter(r=>r.linkStatus==='unresolved').length+'건 · <a href="collaboration.html">실제 계정별 공동 관리 ↗</a>'}const title=titles[role];$('#eyebrow').textContent=title[0];$('#title').innerHTML=esc(title[1])+'<span>.</span>';$('#subtitle').textContent=title[2];$('#accountIcon').textContent=role[0].toUpperCase();$('#accountName').innerHTML=M.names[role]+' 체험<small>로컬 데모 워크스페이스</small>';$('#roles').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.role===role));$('#nav').innerHTML=menu[role].map(([id,icon,n])=>`<button class="nav ${page===id?'active':''}" data-page="${id}" aria-label="${n}">${icon}<span>${n}</span>${id==='approvals'?'<em>REVIEW</em>':''}</button>`).join('');$('#crumb').textContent=menu[role].find(x=>x[0]===page)?.[2]||'대시보드';$('#mainAction').textContent=role==='resident'?'＋ 새로운 관리 요청':role==='expert'?'＋ 점검 기록 작성':'↗ 관리 현황 내보내기';const n=state.notices.filter(x=>role!=='resident'||x.unit===(M.activeUnit||'302')||x.unit==='common');$('#noticeCount').textContent=n.length||'';renderStats();if(page==='home')renderHome();else if(page==='requests')renderRequests();else if(page==='records'||page==='approvals')renderRecords();else if(page==='materials')renderMaterials();else if(page==='knowledge')renderKnowledge();else if(page==='insights')renderInsights();else if(page==='schedule')renderSchedule();else renderReports()}
function renderStats(){const rs=own(),pending=rs.filter(r=>r.stage<4),done=rs.filter(r=>r.stage>=4);const stats=role==='resident'?[['우리 집 관리 요청',rs.filter(r=>r.unit==='302').length,'건','A동 302호 · 나의 공간','⌂'],['점검·보수 이력',records().length,'건','공개 승인된 우리 집 기록','▤'],['진행 중인 요청',pending.length,'건','우리 집 및 공용시설 요청','⌁'],['보수 완료',done.length,'건','완료 결과를 확인해 주세요','✓']]:[['접수된 관리 요청',rs.length,'건','전체 세대 및 공용시설','⌁'],['진행 중인 요청',pending.length,'건','담당자 및 일정 확인 필요','◷'],['보수 완료',done.length,'건','입주자 확인 포함','✓'],[role==='expert'?'기록된 점검':'반복 신고 구간',role==='expert'?state.records.length:M.repeats(state).length,'건',role==='expert'?'원문과 쉬운 설명 연결':'동일 구간 · 복수 세대 집계','◉']];$('#stats').innerHTML=stats.map(([a,n,u,note,icon],i)=>`<div class="stat"><label>${a}</label><span class="stat-icon">${icon}</span><strong class="${i===2?'orange':''}">${n}<small>${u}</small></strong><small>${note}</small></div>`).join('')}
function renderHome(){if(role==='resident')unit=M.activeUnit||'302';let r=own().find(r=>r.id===selectedRequest)||own().find(r=>r.unit===unit)||own()[0];$('#content').innerHTML=`<div class="grid-main">${mapCard()}<section class="card detail">${r?timelineCard(r):'<div class="empty">선택한 요청이 없습니다.</div>'}</section></div><div class="lower-grid"><section class="card"><div class="card-head"><div><div class="eyebrow">${role==='resident'?'MY REQUESTS':'RECENT REQUESTS'}</div><h2 style="margin-top:7px">${role==='resident'?'우리 집의 작은 변화':'최근 접수된 공간의 신호'}</h2></div><button class="text-btn" data-page="requests">모두 보기 ↗</button></div><div class="request-list">${own().slice(0,3).map(requestRow).join('')}</div></section>${role==='expert'?materialSummary():knowledgeCard()}</div><div class="notice-strip"><span>◷</span><div><b>공용시설 점검 안내</b>11월 4일 엘리베이터 정기 점검이 예정되어 있습니다.</div><small>일정은 가상 예시입니다</small></div>`;wireMap()}
function mapCard(){const model=sharedModel;if(!model)return '<section class="card">공간 모델이 없습니다.</section>';return `<section class="card"><div class="card-head"><div><h2>같은 모델의 구조물 위치</h2><p>${esc(model.name)} · ${esc(SpatiaWorkspace.buildingId(model))}</p></div></div><div class="map-bar"><label>조회 호실 <select id="unitSelect" aria-label="조회 호실">${(role==='resident'?[M.activeUnit]:M.units).map(u=>`<option value="${esc(u)}" ${u===unit?'selected':''}>${esc(u)}</option>`).join('')}</select></label><button id="mapSelected" class="small-btn">선택 구조물 분석 ↗</button></div><div class="map-surface"><svg id="plan" viewBox="0 0 760 490" role="img" aria-label="현재 모델 구조물의 XY 평면 투영">${planSvg()}</svg></div><div class="map-bottom">로컬 XYZ의 XY 투영 · 구조물 ID 클릭 · 방 구획·면적 추정 안 함</div></section>`}

function planSvg(){if(!sharedModel)return '';const list=sharedModel.elements.filter(e=>e.unit===unit||e.unit==='common');if(!list.length)return '<text x="40" y="60">이 호실의 연결된 구조물이 없습니다.</text>';const min=[0,1].map(i=>Math.min(...list.map(e=>e.min[i]))),max=[0,1].map(i=>Math.max(...list.map(e=>e.max[i]))),scale=Math.min(640/Math.max(1,max[0]-min[0]),380/Math.max(1,max[1]-min[1]));return list.map(e=>`<g role="button" tabindex="0" data-model-element="${esc(e.id)}" aria-label="${esc(e.name)} 구조물 선택"><rect x="${60+(e.min[0]-min[0])*scale}" y="${50+(e.min[1]-min[1])*scale}" width="${Math.max(4,(e.max[0]-e.min[0])*scale)}" height="${Math.max(4,(e.max[1]-e.min[1])*scale)}" fill="${e.id===selectedElement?'#4a8a70':e.type==='pipe'?'#75aaa5':'#d8e4d6'}" fill-opacity=".45" stroke="#71917c"/><title>${esc(e.id)} · ${esc(e.material)}</title></g>`).join('')}

function wireMap(){const sel=$('#unitSelect');if(sel)sel.onchange=e=>{unit=e.target.value;selectedElement=sharedModel.elements.find(x=>x.unit===unit)?.id||sharedModel.elements[0].id;renderHome()};for(const el of $('#plan').querySelectorAll('[data-model-element]')){const choose=()=>{selectedElement=el.dataset.modelElement;$('#mapSelected').textContent=selectedElement+' 분석 ↗';$('#plan').innerHTML=planSvg();wireMap()};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter')choose()}}$('#mapSelected').onclick=()=>{window.location.href='index.html?element='+encodeURIComponent(selectedElement)}}

function timelineCard(r){return `<div class="detail-eyebrow"><span>REQUEST JOURNEY</span>${badge(r)}</div><h3>${esc(r.title)}</h3><p>${esc(r.id)} · ${unitName(r.unit)}</p><div class="detail-summary">${esc(r.events.at(-1)?.text)}<br>담당: ${esc(r.assignee||'배정 대기')}<br>예정: ${dateText(r.date)}</div>${timeline(r)}<button class="outline-btn" data-open="${esc(r.id)}">${role==='manager'?'담당자·처리 상태 관리':'요청 상세 보기'} &nbsp; ↗</button>`}
function timeline(r){return `<ol class="timeline">${M.stages.map((s,i)=>`<li class="${r.stage>i?'done':r.stage===i?'current':''}"><i>${r.stage>i?'✓':''}</i><b>${s}</b><small>${i===r.stage?(r.date?'예정 '+dateText(r.date):'다음 안내를 기다려 주세요'):i>r.stage?'이전 단계 완료 후 진행':'처리 이력 확인 가능'}</small></li>`).join('')}</ol>`}
function requestRow(r){return `<div class="request-row" role="button" tabindex="0" data-open="${esc(r.id)}"><span class="request-icon">${r.type==='누수·습기'?'♧':'⌁'}</span><div><h4>${esc(r.title)}</h4><small>${unitName(r.unit)} · ${esc(r.element)} · ${dateText(r.created)}</small></div>${badge(r)}<span class="arrow">↗</span></div>`}
function knowledgeCard(){const r=records().find(r=>r.published);return `<section class="card"><div class="card-head"><div><div class="eyebrow">BUILDING, IN PLAIN WORDS</div><h2 style="margin-top:7px">어려운 기록을 쉬운 이야기로</h2></div><button class="text-btn" data-page="knowledge">더 보기 ↗</button></div><div class="knowledge"><div class="term-title"><span class="term-icon">✧</span> ${r?esc(r.term):'건축 전문용어 해설'} <span class="tag">${r?'공개 승인':'용어 사전'}</span></div><div class="tech-text">${r?(role==='resident'?'공간 ID '+esc(r.element)+'에 연결된 전문가 검토 설명입니다.':esc(r.raw)):esc(M.terms['결로'].raw)}</div><div class="plain-box"><b>쉽게 풀어 설명하면</b><p>${r?esc(r.plain):esc(M.terms['결로'].plain)}</p><small>${r?'출처 '+esc(r.id)+' · 전문가 검토 완료':'사전 기반 예시 · AI 생성 아님'}</small></div></div></section>`}
function materialSummary(){return `<section class="card"><div class="card-head"><div><div class="eyebrow">MATERIAL TRACEABILITY</div><h2 style="margin-top:7px">공간에서 시공 기록까지</h2></div><button class="text-btn" data-page="materials">기록 보기 ↗</button></div><div class="knowledge"><div class="chips"><span class="chip">${esc(selectedElement)}</span><span class="chip">벽체 W01</span></div><p class="tech-text">철근콘크리트 + 석고보드 마감<br>시공 2021.05.18 · 인접 배관 P-02</p><div class="plain-box"><b>기록은 원문을 보존합니다</b><p>점검 결과와 입주자용 쉬운 설명을 함께 작성하고, 검토·공개 절차를 거쳐 전달합니다.</p></div></div></section>`}
function renderRequests(){let rs=own().filter(r=>(statusFilter==='all'||(statusFilter==='active'?r.stage<4:r.stage>=4))&&(r.id+' '+r.title+' '+r.unit+' '+r.element).toLowerCase().includes(filter.toLowerCase()));$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>${role==='resident'?'나의 관리 요청':'공간 기반 관리 요청'}</h2><p>${role==='resident'?'302호와 공용부 요청만 표시됩니다.':'공간 ID로 담당자·일정·처리 이력을 추적합니다.'}</p></div><span class="tag">${rs.length}건</span></div><div class="filters"><input id="search" placeholder="요청번호, 호실, 공간 ID 검색" aria-label="요청 검색" value="${esc(filter)}"><select id="statusFilter" aria-label="처리 상태 필터"><option value="all">전체 상태</option><option value="active" ${statusFilter==='active'?'selected':''}>진행 중</option><option value="done" ${statusFilter==='done'?'selected':''}>보수 완료</option></select><button class="small-btn" id="applyFilter">검색</button></div><div class="table-wrap"><table><thead><tr><th>요청 / 공간</th><th>유형</th><th>처리 상태</th><th>담당자</th><th>예정 일정</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.title)}<br><small>${esc(r.id)} · ${unitName(r.unit)} · ${esc(r.element)}</small></td><td>${esc(r.type)}</td><td>${badge(r)}</td><td>${esc(r.assignee||'배정 대기')}</td><td>${dateText(r.date)}</td><td><button class="text-btn" data-open="${esc(r.id)}">${role==='manager'?'관리':'상세'} ↗</button></td></tr>`).join('')}</tbody></table>${!rs.length?'<div class="empty">조건에 맞는 요청이 없습니다.</div>':''}</div></section>`;$('#applyFilter').onclick=()=>{filter=$('#search').value;statusFilter=$('#statusFilter').value;renderRequests()};$('#search').onkeydown=e=>{if(e.key==='Enter')$('#applyFilter').click()};$('#statusFilter').onchange=()=>$('#applyFilter').click()}
function photos(arr){return arr?.length?`<div class="preview-photos">${arr.filter(x=>/^data:image\/(png|jpeg|webp);base64,/.test(x)).map(x=>`<a href="${x}" target="_blank" rel="noopener"><img class="photo" src="${x}" alt="첨부 현장 사진"></a>`).join('')}</div>`:'<div class="image-placeholder">등록된 사진 없음 · 가상 사례에는 사진이 포함되지 않았습니다</div>'}
function requestDetail(id){const r=own().find(r=>r.id===id);if(!r)return toast('현재 화면에서 볼 수 없는 요청입니다.');selectedRequest=id;show(`<div class="eyebrow">${esc(r.id)} · ${esc(r.element)}</div><h2>${esc(r.title)}</h2>${badge(r)}<dl class="kv"><dt>위치</dt><dd>${unitName(r.unit)} · ${spaceName(r.space)} · ${esc(r.zone)}</dd>${r.parent?`<dt>원 요청</dt><dd><button class="text-btn" data-open="${esc(r.parent)}">${esc(r.parent)} ↗</button></dd>`:''}<dt>요청 내용</dt><dd>${esc(r.description)}</dd><dt>담당자</dt><dd>${esc(r.assignee||'배정 대기')}</dd><dt>예정 일정</dt><dd>${dateText(r.date)}</dd></dl><div class="tabs"><button class="active" data-detail-tab="history">처리 이력</button><button data-detail-tab="photos">보수 전후 사진</button><button data-detail-tab="records">점검 설명</button></div><div id="requestTab"></div><div id="requestActions"></div>`);function draw(tab){$('#requestTab').innerHTML=tab==='photos'?`<h4>보수 전</h4>${photos(r.before)}<h4>보수 후</h4>${photos(r.after)}`:tab==='records'?recordCards(records().filter(x=>x.request===id)):r.events.map(e=>`<div class="event">${esc(e.text)}<small>${dateText(e.at)} ${esc(e.at.slice(11,16))} · ${esc(e.by)}</small></div>`).join('');$('#dialogBody').querySelectorAll('[data-detail-tab]').forEach(b=>b.classList.toggle('active',b.dataset.detailTab===tab))}$('#dialogBody').querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>draw(b.dataset.detailTab));draw('history');$('#requestActions').innerHTML=role==='manager'?`<div class="dialog-actions"><button class="primary" id="manageRequest">담당자·일정·상태 변경</button></div>`:role==='expert'?`<div class="dialog-actions"><button class="primary" id="recordRequest">이 요청 점검 기록 작성</button></div>`:r.unit==='302'&&r.stage>=4?`<div class="notice">${r.stage===5?'입주자 확인 완료 · 만족도 '+r.rating+'/5':'보수 결과를 확인하고 만족도 또는 미해결 사유를 남겨주세요.'}</div><div class="dialog-actions"><button class="outline-btn" id="reopen">미해결 · 재요청</button>${r.stage===4?'<button class="primary" id="confirmDone">완료 확인·만족도</button>':''}</div>`:'';if($('#manageRequest'))$('#manageRequest').onclick=()=>manageRequest(id);if($('#recordRequest'))$('#recordRequest').onclick=()=>recordForm(null,id);if($('#reopen'))$('#reopen').onclick=()=>reopenRequest(id);if($('#confirmDone'))$('#confirmDone').onclick=()=>confirmRequest(id)}
async function readPhotos(input){const files=[...input.files];if(files.length>2)throw Error('사진은 최대 2장까지 첨부할 수 있습니다.');return Promise.all(files.map(f=>new Promise((resolve,reject)=>{if(!['image/png','image/jpeg','image/webp'].includes(f.type))return reject(Error('PNG, JPG, WebP 사진만 첨부할 수 있습니다.'));if(f.size>800*1024)return reject(Error('사진 한 장은 800KB 이하로 선택하세요.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('사진을 읽지 못했습니다.'));reader.readAsDataURL(f)})))}
function newRequest(){const allowed=sharedModel.elements.filter(e=>role!=='resident'||e.unit===M.activeUnit||e.unit==='common');show(`<div class="eyebrow">SPACE-BASED SERVICE REQUEST · LOCAL DEMO</div><h2>새로운 관리 요청</h2><p class="notice">같은 건물의 실제 구조물 ID를 선택합니다. 이 역할 체험은 브라우저에만 저장됩니다. 계정 간 전달은 공동 관리를 이용하세요.</p><form id="requestForm"><label class="field">대상 구조물<select id="requestElement" required>${allowed.map(e=>`<option value="${esc(e.id)}" ${e.id===selectedElement?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></label><label class="field">불편 사항 유형<select id="requestType">${['누수·습기','벽체 균열','소음·진동','시설물 고장','기타'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">상세 설명<textarea id="requestDescription" required minlength="5" maxlength="1500" placeholder="발견한 시점과 불편 사항을 알려주세요."></textarea></label><details class="spatia-optional"><summary>제목·사진 추가 <span class="spatia-form-hint">선택</span></summary><label class="field">제목<input id="requestTitle" maxlength="80"></label><label class="field">현장 사진<input id="requestPhotos" type="file" accept="image/png,image/jpeg,image/webp" multiple><small>최대 2장 · 각 800KB 이하</small></label></details><div class="dialog-actions"><button class="primary">요청 등록 · 브라우저에 저장</button></div></form>`);$('#requestForm').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;try{const e=allowed.find(e=>e.id===$('#requestElement').value);if(!e)throw Error('대상 구조물을 확인하세요.');const description=$('#requestDescription').value.trim();if(description.length<5)throw Error('상세 설명을 5자 이상 입력하세요.');const before=await readPhotos($('#requestPhotos')),type=$('#requestType').value,title=$('#requestTitle').value.trim()||(e.name+' '+type).slice(0,80),id='REQ-'+crypto.randomUUID().slice(0,8).toUpperCase();if(commit(next=>{next.requests.unshift({id,...SpatiaWorkspace.ids(sharedModel,e),unit:e.unit,space:e.type,element:e.id,zone:e.direction||'구조물 위치',type,title,description,stage:0,assignee:'',date:'',created:M.now(),before,after:[],linkStatus:'linked',events:[{at:M.now(),text:'통합 구조물 ID로 등록 · 브라우저 데모',by:M.names[role]}]})})){close();selectedRequest=id;page='requests';render();toast(id+' 등록 완료')}}catch(e){toast(e.message)}finally{submit.disabled=false}}}

function manageRequest(id){if(role!=='manager')return;const r=state.requests.find(r=>r.id===id);show(`<div class="eyebrow">REQUEST OPERATIONS</div><h2>${esc(r.title)} 관리</h2><form id="manageForm"><div class="form-grid"><label class="field">담당자<input required id="assignee" value="${esc(r.assignee)}" maxlength="80" placeholder="예: 김지훈 · 건축 점검"></label><label class="field">예정 일정<input type="date" id="scheduleDate" value="${esc(r.date)}"></label></div><label class="field">처리 단계<select id="newStage">${M.stages.slice(0,5).map((n,i)=>`<option value="${i}" ${i<r.stage?'disabled':''} ${i===Math.min(r.stage,4)?'selected':''}>${n}</option>`).join('')}</select><small>입주자 확인은 입주자 화면에서만 진행합니다. 보수 예정·완료 단계에는 일정이 필요합니다.</small></label><label class="field">진행 안내<textarea required id="progressNote" maxlength="1000" placeholder="현재 진행 내용, 일정 변경 사유, 다음 안내 사항을 입력하세요."></textarea></label><label class="field">보수 후 사진 추가 (선택)<input type="file" multiple accept="image/png,image/jpeg,image/webp" id="afterPhotos"><small>최대 2장 · 각 800KB 이하 · 기존 보수 후 사진을 대체합니다.</small></label><div class="dialog-actions"><button class="primary" type="submit" ${r.stage===5?'disabled':''}>처리 정보 저장</button></div></form>${r.stage===5?'<p>입주자 확인이 완료된 요청입니다.</p>':''}`);$('#manageForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const assignee=$('#assignee').value.trim(),date=$('#scheduleDate').value,stage=+$('#newStage').value,note=$('#progressNote').value.trim(),images=await readPhotos($('#afterPhotos'));if(!note)throw Error('진행 안내를 입력하세요.');if(commit(next=>{M.transition(next,id,stage,assignee,date,role);const x=next.requests.find(x=>x.id===id);x.events.push({at:M.now(),text:note,by:'관리자'});if(images.length)x.after=images})){requestDetail(id);toast('담당자·일정·처리 이력을 저장했습니다.')}}catch(err){toast(err.message)}finally{b.disabled=false}}}
function confirmRequest(id){const r=own().find(x=>x.id===id);if(role!=='resident'||r?.unit!==(M.activeUnit||'302')||r.stage!==4)return;show(`<h2>보수 완료 확인</h2><form id="confirmForm"><label class="field">만족도<select id="rating"><option value="5">5 · 매우 만족</option><option value="4">4 · 만족</option><option value="3">3 · 보통</option><option value="2">2 · 불만족</option><option value="1">1 · 매우 불만족</option></select></label><label class="field">확인 의견<textarea id="feedback" maxlength="600" placeholder="보수 결과와 재발 여부를 남겨주세요."></textarea></label><div class="dialog-actions"><button class="primary">완료 확인 저장</button></div></form>`);$('#confirmForm').onsubmit=e=>{e.preventDefault();const rating=+$('#rating').value,feedback=$('#feedback').value.trim();if(commit(next=>{const x=next.requests.find(x=>x.id===id);x.stage=5;x.rating=rating;x.feedback=feedback;x.events.push({at:M.now(),text:`입주자 완료 확인 · 만족도 ${rating}/5 ${feedback}`,by:'입주자'})})){requestDetail(id);toast('완료 확인과 만족도를 저장했습니다.')}}}
function reopenRequest(id){show(`<h2>미해결 문제 재요청</h2><p>이전 처리 이력을 보존하고, 원래 요청과 연결된 새 요청을 만듭니다.</p><form id="reopenForm"><label class="field">미해결 또는 재발 내용<textarea required minlength="5" maxlength="1200" id="reopenReason"></textarea></label><div class="dialog-actions"><button class="primary">재요청 등록</button></div></form>`);$('#reopenForm').onsubmit=e=>{e.preventDefault();const reason=$('#reopenReason').value.trim();if(reason.length<5)return toast('재요청 사유를 5자 이상 입력하세요.');const original=state.requests.find(r=>r.id===id),newId='REQ-'+new Date().getFullYear()+'-'+crypto.randomUUID().slice(0,8).toUpperCase();if(commit(next=>{next.requests.unshift({...M.clone(original),id:newId,parent:id,title:'[재요청] '+original.title,description:reason,created:M.now(),stage:0,date:'',assignee:'',after:[],rating:null,feedback:'',events:[{at:M.now(),text:`원 요청 ${id}에서 재요청 · ${reason}`,by:'입주자'}]});next.notices.unshift({id:'N-'+Date.now(),unit:original.unit,at:M.now(),text:newId+' 미해결 재요청 등록'})})){close();page='requests';render();toast('새 요청을 등록하고 기존 이력을 연결했습니다.')}}}
function recordCards(rs){return rs.length?rs.map(r=>`<article class="record"><h4>${esc(r.id)} · ${esc(r.element)} <span class="tag">${r.published?'공개 승인':r.reviewed?'전문가 검토 완료':'검토 대기'}</span></h4>${role!=='resident'?`<p><b>전문가 원문</b><br>${esc(r.raw)}</p>`:''}<div class="plain-box"><b>쉬운 설명</b><p>${esc(r.plain||'작성 대기')}</p><small>다음 확인: ${esc(r.next||'미정')}<br>출처 ${esc(r.id)} · ${esc(r.author)} · ${dateText(r.at)}</small></div>${role!=='resident'?`<div class="dialog-actions">${r.revisions?.length?`<button class="small-btn" data-revisions="${esc(r.id)}">수정 이력 (${r.revisions.length})</button>`:''}${role==='expert'?`<button class="small-btn" data-edit-record="${esc(r.id)}">기록 수정·검토</button>`:''}${role==='manager'&&!r.published?`<button class="small-btn" data-publish="${esc(r.id)}" ${!r.reviewed?'disabled':''}>공개 승인</button>`:''}${role==='manager'&&r.published?`<button class="small-btn" data-unpublish="${esc(r.id)}">공개 철회</button>`:''}</div>`:''}</article>`).join(''):'<div class="empty">공개 승인된 관련 점검 설명이 없습니다.</div>'}
function renderRecords(){const rs=records();$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>${page==='approvals'?'검토된 쉬운 설명 공개 승인':'공간별 점검·보수 기록'}</h2><p>${role==='resident'?'우리 집과 공용부의 공개 승인된 기록만 표시합니다.':'전문가 원문 보존 → 쉬운 설명 작성 → 전문가 검토 → 관리자 공개 승인'}</p></div>${role==='expert'?'<button class="small-btn" id="newRecord">＋ 기록 작성</button>':''}</div><div class="knowledge">${recordCards(rs)}</div></section>`;if($('#newRecord'))$('#newRecord').onclick=()=>recordForm()}
function recordForm(id=null,requestId=null){if(role!=='expert')return;const r=state.records.find(r=>r.id===id),req=state.requests.find(r=>r.id===(requestId||r?.request));show(`<div class="eyebrow">EXPERT RECORD · ORIGINAL PRESERVED</div><h2>${r?'점검 기록 수정':'점검 기록 작성'}</h2><form id="recordForm"><div class="form-grid"><label class="field">연결 요청<select id="recordRequest"><option value="">요청 없이 공간 기록</option>${state.requests.map(x=>`<option value="${esc(x.id)}" ${x.id===req?.id?'selected':''}>${esc(x.id)} · ${unitName(x.unit)}</option>`).join('')}</select></label><label class="field">기록자<input required maxlength="80" id="recordAuthor" value="${esc(r?.author||'김지훈 · 건축 점검')}"></label></div><label class="field">공간·구조물 ID<select required id="recordElement">${sharedModel.elements.map(e=>`<option value="${esc(e.id)}" ${e.id===(r?.element||req?.element||selectedElement)?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select><small>연결 요청을 선택하면 해당 요청의 공간 ID가 적용됩니다.</small></label><label class="field">기술 용어<select id="recordTerm">${Object.keys(M.terms).map(t=>`<option ${t===(r?.term||'결로')?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">전문가 원문<textarea required id="recordRaw" maxlength="2500">${esc(r?.raw||'')}</textarea></label><button type="button" class="small-btn" id="draftPlain" style="margin-top:12px">✧ 용어 사전으로 설명 초안 채우기</button><label class="field">입주자용 쉬운 설명<textarea required id="recordPlain" maxlength="1800">${esc(r?.plain||'')}</textarea><small>사전 기반 초안은 원문의 개별 상황을 자동 해석하지 않습니다. 원문과 대조하고 미확정 사항을 유지해 수정하세요.</small></label><label class="field">다음 확인 사항<input id="recordNext" maxlength="500" value="${esc(r?.next||'')}"></label><label class="field"><input type="checkbox" id="recordReviewed"> 원문과 쉬운 설명을 대조하고 검토했습니다.</label><div class="notice">기록 수정 시 기존 공개는 철회되고 재승인이 필요합니다. 이전 원문은 수정 이력에 보존합니다. 이 기능은 AI 모델을 호출하지 않는 사전 기반 데모입니다.</div><div class="dialog-actions"><button class="primary">기록 저장 · 관리자 검토 요청</button></div></form>`);$('#recordRequest').onchange=()=>{const q=state.requests.find(q=>q.id===$('#recordRequest').value);if(q)$('#recordElement').value=q.element};$('#draftPlain').onclick=()=>{const t=M.terms[$('#recordTerm').value];$('#recordPlain').value=t.plain;$('#recordNext').value=t.next;$('#recordReviewed').checked=false};$('#recordForm').onsubmit=e=>{e.preventDefault();const request=$('#recordRequest').value,q=state.requests.find(q=>q.id===request),element=$('#recordElement').value.trim(),raw=$('#recordRaw').value.trim(),plain=$('#recordPlain').value.trim(),next=$('#recordNext').value.trim(),author=$('#recordAuthor').value.trim(),reviewed=$('#recordReviewed').checked,term=$('#recordTerm').value;if(!raw||!plain||!author||!element)return toast('필수 기록 내용을 입력하세요.');const linked=sharedModel?.elements.find(e=>e.id===element);if(!linked)return toast('현재 모델에 등록된 구조물 ID를 선택하세요.');const recordUnit=linked.unit;if(q&&element!==q.element)return toast('연결 요청의 공간 ID와 일치해야 합니다.');if(commit(nextState=>{const rec={id:id||'REC-'+crypto.randomUUID().slice(0,8),request,...SpatiaWorkspace.ids(sharedModel,linked),unit:recordUnit,element,raw,plain,next,author,term,reviewed,published:false,at:M.now(),revisions:r?[...(r.revisions||[]),{raw:r.raw,plain:r.plain,next:r.next,author:r.author,at:r.at}]:[]};if(r)nextState.records[nextState.records.findIndex(x=>x.id===id)]=rec;else nextState.records.unshift(rec)})){close();page='records';render();toast('원문과 쉬운 설명을 저장했습니다. 공개 승인을 기다립니다.')}}}
function openElement(suffix){const mat=state.materials.find(m=>m.element===suffix)||state.materials[0],element=`A-${unit}-${mat.element}`;if(role==='resident'){show(`<div class="eyebrow">MY SPACE · ${esc(element)}</div><h2>${esc(mat.name)}</h2><p>현재 선택한 공간의 공개 승인된 설명입니다.</p>${recordCards(records().filter(r=>r.element===element))}<div class="dialog-actions"><button class="primary" id="elementRequest">이 위치에 관리 요청</button></div>`);$('#elementRequest').onclick=newRequest;return}show(`<div class="eyebrow">SPATIAL ELEMENT · ${esc(element)}</div><h2>${esc(mat.name)}</h2><dl class="kv"><dt>자재</dt><dd>${esc(mat.material)}</dd><dt>시공일</dt><dd>${dateText(mat.installed)}</dd><dt>최근 점검</dt><dd>${dateText(mat.inspection)}</dd><dt>품질 검사</dt><dd>${esc(mat.quality)}</dd><dt>주변 배관</dt><dd>${esc(mat.pipe)}</dd><dt>기록 참고</dt><dd>${esc(mat.note)}</dd></dl><h4>연결된 점검 기록</h4>${recordCards(records().filter(r=>r.element===element))}<div class="dialog-actions">${role==='expert'?'<button class="outline-btn" id="editMaterial">자재·시공 정보 편집</button><button class="primary" id="elementRecord">점검 기록 추가</button>':''}</div>`);if($('#elementRecord'))$('#elementRecord').onclick=()=>recordForm();if($('#editMaterial'))$('#editMaterial').onclick=()=>materialForm(mat.id)}
function renderMaterials(){$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>자재·시공 정보 라이브러리</h2><p>현재 공간 모델의 구조물 ID별 자재·시공 기록입니다. 공간 분석에서 편집한 값이 같은 모델에 반영됩니다.</p></div></div><div class="table-wrap"><table><thead><tr><th>구조물</th><th>자재</th><th>시공일</th><th>품질 검사</th><th></th></tr></thead><tbody>${state.materials.map(m=>`<tr><td>${esc(m.element)} · ${esc(m.name)}</td><td>${esc(m.material)}</td><td>${dateText(m.installed)}</td><td>${esc(m.quality)}</td><td><button class="text-btn" data-material="${m.id}">편집 ↗</button></td></tr>`).join('')}</tbody></table></div></section>`}
function materialForm(id){const m=state.materials.find(x=>x.id===id);if(!m)return;show(`<h2>${esc(m.name)} · 통합 자재 정보</h2><p>공간 분석과 유지관리가 같은 구조물 데이터를 사용합니다. 중복 자재 기록을 별도로 편집하지 않습니다.</p><p>${esc(m.element)} · ${esc(m.material)}</p><a class="button primary" href="index.html?element=${encodeURIComponent(m.element)}">공간 분석에서 속성 확인·편집 ↗</a>`)}

function renderKnowledge(){$('#content').innerHTML=`<div class="full-grid"><section class="card"><div class="card-head"><div><h2>건축 전문용어, 쉽게 이해하기</h2><p>사전 기반 해설 · AI 자동 생성 및 안전 판정 기능이 아닙니다.</p></div></div><div class="knowledge"><label class="field">알아볼 전문용어<select id="termSelect">${Object.keys(M.terms).map(t=>`<option>${t}</option>`).join('')}</select></label><div id="termExplanation"></div><label class="field">궁금한 질문<input id="question" placeholder="예: 결로와 누수는 무엇이 다른가요?" maxlength="300"></label><button class="small-btn" id="ask" style="margin-top:12px">관련 용어 찾아보기</button><p id="answer"></p></div></section><section class="card"><div class="card-head"><div><h2>우리 공간에 연결된 설명</h2><p>출처와 검토 상태를 함께 확인하세요.</p></div></div><div class="knowledge">${recordCards(records().filter(r=>r.published))}</div></section></div>`;function draw(){const t=$('#termSelect').value,d=M.terms[t];$('#termExplanation').innerHTML=`<p class="tech-text">${esc(d.raw)}</p><div class="plain-box"><b>쉽게 풀어 설명하면</b><p>${esc(d.plain)}</p><small>다음 확인 사항: ${esc(d.next)}</small></div>`}$('#termSelect').onchange=draw;draw();$('#ask').onclick=()=>{const q=$('#question').value,t=Object.keys(M.terms).find(t=>q.includes(t));$('#answer').textContent=t?M.terms[t].plain+' 이 해설은 일반적인 사전 설명이며 우리 집의 원인을 확정하지 않습니다.':'해당 질문을 자동 해석할 수 없습니다. 용어를 선택하거나 공간의 공개 점검 기록을 확인하세요.';if(t){$('#termSelect').value=t;draw()}}}
function renderInsights(){if(role==='resident')return;const groups=M.repeats(state);$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>반복 신고 구간 탐색</h2><p>같은 구간·유형에 2개 이상 세대가 신고한 사례를 집계합니다. 반복 원인이나 구조적 결함을 판정하지 않습니다.</p></div><span class="tag">규칙 기반 집계</span></div><div class="knowledge">${groups.length?groups.map(g=>`<div class="record"><h4>${esc(g.zone)} · ${esc(g.type)}</h4><div class="chips"><span class="chip">${g.requests.length}건</span><span class="chip">${g.units.length}개 세대</span>${g.units.map(u=>`<span class="chip">${unitName(u)}</span>`).join('')}</div><p>동일 구간의 신고가 모였습니다. 현장 측정, 외벽 접합부와 배관 이력 대조를 통해 원인 연관성을 확인하세요.</p>${g.requests.map(requestRow).join('')}</div>`).join(''):'<div class="empty">반복 신고 기준에 해당하는 구간이 없습니다.</div>'}</div></section><div class="insight-grid">${['누수·습기','벽체 균열','시설물 고장'].map(t=>`<section class="card insight-card"><div class="eyebrow">REQUEST DISTRIBUTION</div><h2 style="margin-top:8px">${t}</h2><strong>${state.requests.filter(r=>r.type===t).length}<small style="font-size:11px"> 건</small></strong><p>공간 ID에 연결된 현재 요청 수입니다. 재요청은 별도 건으로 집계합니다.</p></section>`).join('')}</div>`}
function renderSchedule(){const rs=own().filter(r=>r.date).sort((a,b)=>a.date.localeCompare(b.date));$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>${role==='resident'?'우리 집·공용시설 일정':'건물 점검·보수 일정'}</h2><p>관리자가 등록한 예정일과 현재 진행 상태를 표시합니다. 가상 사례의 예시 일정입니다.</p></div></div><div class="table-wrap"><table><thead><tr><th>예정일</th><th>위치 / 작업</th><th>담당자</th><th>상태</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${dateText(r.date)}</td><td>${unitName(r.unit)} · ${esc(r.title)}</td><td>${esc(r.assignee)}</td><td>${badge(r)}</td><td><button class="text-btn" data-open="${r.id}">상세 ↗</button></td></tr>`).join('')}</tbody></table></div></section>`}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('파일을 내보냈습니다.')}
function csvValue(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCSV(){const rows=[['요청번호','호실','공간ID','구간','제목','유형','상태','담당자','예정일'],...own().map(r=>[r.id,r.unit,r.element,r.zone,r.title,r.type,M.stages[r.stage],r.assignee,r.date])];download('build-intelligence-requests.csv','\uFEFF'+rows.map(row=>row.map(csvValue).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function renderReports(){$('#content').innerHTML=`<section class="card"><div class="card-head"><div><h2>관리 데이터 내보내기</h2><p>현재 브라우저에서 체험한 데이터를 저장합니다.</p></div></div><div class="knowledge"><div class="notice">CSV에는 요청 현황이 포함됩니다. JSON에는 신고 설명·사진·비공개 전문가 기록을 포함한 전체 데모 데이터가 들어갑니다. 외부 공유 시 내용을 확인하세요.</div><div class="dialog-actions" style="justify-content:flex-start"><button class="primary" id="csvExport">요청 현황 CSV</button><button class="outline-btn" id="jsonExport">전체 데모 JSON 백업</button></div></div></section>`;$('#csvExport').onclick=exportCSV;$('#jsonExport').onclick=()=>download('build-intelligence-demo.json',JSON.stringify({exportedAt:M.now(),dataType:'browser-local-demo',...state},null,2),'application/json')}
function notices(){show(`<div class="eyebrow">WORKSPACE UPDATES</div><h2>점검·관리 알림</h2><p>현재 브라우저의 알림입니다. 이메일·문자·푸시를 발송하지 않습니다.</p>${state.notices.filter(n=>role!=='resident'||n.unit==='302'||n.unit==='common').map(n=>`<div class="event">${esc(n.text)}<small>${unitName(n.unit)} · ${dateText(n.at)}</small></div>`).join('')}`)}
function guide(){show(`<div class="eyebrow">SPATIA 2.0</div><h2>세 가지 역할로 이어지는 공간의 기록</h2><p>① 입주자: 도면 공간 선택 → 요청·사진 등록 → 진행 이력 확인 → 완료 확인·재요청<br>② 관리자: 전체 요청 조회 → 담당자·일정·상태 관리 → 검토된 설명 공개 승인 → 반복 신고 구간 확인<br>③ 전문가: 벽체·자재 확인 → 원문·쉬운 설명 작성 → 전문가 검토 체크 → 관리자 승인 요청</p><div class="notice">이 사이트는 가상 데이터와 브라우저 저장소를 사용하는 기능 데모입니다. 역할 버튼은 실제 인증·권한 통제가 아니며, 다른 기기·사용자와 데이터가 동기화되지 않습니다. 입주자 체험은 302호와 공용부로 화면을 제한합니다.</div><p>도면은 가상 평면도이며 입체 보기는 시각적 변환입니다. 실제 BIM·IFC·실시간 센서·AI 모델 호출은 연결하지 않았습니다. 쉬운 해설은 사전 기반 예시이며, 구조 안전이나 하자 원인을 자동 판정하지 않습니다.</p><p>사진은 PNG/JPG/WebP 최대 2장, 각 800KB까지 저장할 수 있습니다. 저장소 용량을 초과하면 변경을 저장하지 않고 안내합니다. 브라우저 데이터 삭제 시 기록이 사라집니다. 기존 실내 GIS 분석은 사이드바 메뉴에서 열 수 있습니다.</p>`)}
$('#roles').onclick=e=>{const b=e.target.closest('[data-role]');if(b){role=b.dataset.role;page='home';filter='';statusFilter='all';unit='302';close();render()}};$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;render()}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-open],[data-page],[data-publish],[data-unpublish],[data-edit-record],[data-material],[data-revisions]');if(!b)return;if(b.dataset.open)requestDetail(b.dataset.open);else if(b.dataset.page&&b.closest('#content')){page=b.dataset.page;render()}else if(b.dataset.publish&&role==='manager'){if(commit(next=>M.publish(next,b.dataset.publish))){close();toast('전문가 검토된 설명을 공개했습니다.')}}else if(b.dataset.unpublish&&role==='manager'){if(commit(next=>{next.records.find(r=>r.id===b.dataset.unpublish).published=false})){close();toast('공개를 철회했습니다.')}}else if(b.dataset.editRecord)recordForm(b.dataset.editRecord);else if(b.dataset.material)materialForm(b.dataset.material);else if(b.dataset.revisions&&role!=='resident'){const rec=state.records.find(r=>r.id===b.dataset.revisions);show(`<h2>${esc(rec.id)} 수정 이력</h2><p>저장된 이전 원문과 쉬운 설명입니다. 현재 기록과 구분해 보존합니다.</p>${rec.revisions.map(v=>`<article class="record"><h4>${esc(v.author)} · ${dateText(v.at)}</h4><p>이전 원문: ${esc(v.raw)}</p><p>이전 설명: ${esc(v.plain)}</p></article>`).join('')}`)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role="button"]'))e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))});
$('#mainAction').onclick=()=>role==='resident'?newRequest():role==='expert'?recordForm():exportCSV();$('#help').onclick=guide;$('#dataGuide').onclick=guide;$('#notifications').onclick=notices;
window.addEventListener('storage',e=>{if(e.key===KEY){try{const s=JSON.parse(e.newValue);if(s?.version===2){state=s;close();render();toast('다른 탭에서 변경된 데모 데이터를 반영했습니다.')}}catch{}}});
if(['resident','manager','expert'].includes(window.location?.hash?.slice(1)))role=window.location.hash.slice(1);
render();

window.addEventListener('storage',event=>{if(event.key!==SpatiaWorkspace.MODEL_KEY)return;if($('#dialog').open){toast('공간 모델이 변경됐습니다. 입력을 마친 후 새로고침하세요.');return}try{sharedModel=GeoEngine.validate(JSON.parse(event.newValue));M.activeUnit=sharedModel.elements.some(e=>e.unit==='302')?'302':sharedModel.elements[0].unit;M.units=[...new Set(sharedModel.elements.map(e=>e.unit))];state=SpatiaWorkspace.reconcile(state,sharedModel);localStorage.setItem(KEY,JSON.stringify(state));unit=M.activeUnit;selectedElement=sharedModel.elements[0].id;render();toast('같은 구조물 ID의 자재·공간 정보를 동기화했습니다.')}catch(e){toast(e.message)}});
